void test_FR_008_01(void)
{
    motion_sample_t sample;

    (void)motion_processor_process(0, 0, 8192, 0U, &sample);
    (void)motion_processor_process(0, 0, 8192, 1000U, &sample);

    motion_processor_status_t status =
        motion_processor_process(8192, 0, 8192, 1010U, &sample);

    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(1000, sample.x_millig);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_WIDE_TURN, sample.event);
}
